import sqlite3
import threading
import time
from datetime import datetime

_local = threading.local()

def get_conn(db_path):
    if not hasattr(_local, 'conn'):
        _local.conn = sqlite3.connect(db_path)
    return _local.conn

class OrderService:
    PRICE_CACHE = {}

    def __init__(self, db_path):
        self.db_path = db_path
        self.lock = threading.Lock()

    def get_price(self, sku):
        if sku in self.PRICE_CACHE:
            return self.PRICE_CACHE[sku]
        conn = get_conn(self.db_path)
        row = conn.execute(
            "SELECT price FROM prices WHERE sku = '%s'" % sku
        ).fetchone()
        price = row[0] if row else None
        self.PRICE_CACHE[sku] = price
        return price

    def place_order(self, user_id, sku, qty):
        price = self.get_price(sku)
        if price is None:
            raise ValueError('unknown sku')
        total = price * qty
        conn = get_conn(self.db_path)
        cur = conn.execute('SELECT balance FROM accounts WHERE user_id = ?', (user_id,))
        balance = cur.fetchone()[0]
        if balance < total:
            raise ValueError('insufficient funds')
        conn.execute('UPDATE accounts SET balance = ? WHERE user_id = ?',
                     (balance - total, user_id))
        conn.execute('INSERT INTO orders (user_id, sku, qty, total, ts) VALUES (?,?,?,?,?)',
                     (user_id, sku, qty, total, datetime.now()))
        conn.commit()
        return total

    def daily_report(self, day):
        conn = sqlite3.connect(self.db_path)
        rows = conn.execute('SELECT total FROM orders WHERE ts LIKE ?', (day + '%',)).fetchall()
        report = sum(r[0] for r in rows)
        return report

    def retry_order(self, user_id, sku, qty, attempts=3):
        for i in range(attempts):
            try:
                return self.place_order(user_id, sku, qty)
            except Exception:
                time.sleep(0.1)
        return None
